testsCode:
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { gerarContagem } from './solution.mjs';

async function coletar(gerador) {
  const valores = [];
  for await (const valor of gerador) {
    valores.push(valor);
  }
  return valores;
}

test('gera de 1 até 3 esperando 2ms entre cada número', async () => {
  assert.deepEqual(await coletar(gerarContagem(3, 2)), [1, 2, 3]);
});

test('n = 1 gera um único número', async () => {
  assert.deepEqual(await coletar(gerarContagem(1, 5)), [1]);
});

test('n = 0 não gera nada', async () => {
  assert.deepEqual(await coletar(gerarContagem(0, 3)), []);
});

test('rejeita quando n é negativo', async () => {
  await assert.rejects(() => coletar(gerarContagem(-1, 2)), /maior ou igual/);
});

solutionCode:
function espera(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

export async function* gerarContagem(n, ms) {
  if (typeof n !== 'number' || n < 0 || typeof ms !== 'number' || ms < 1) {
    throw new Error('n deve ser maior ou igual a zero e ms deve ser maior que zero');
  }
  for (let i = 1; i <= n; i += 1) {
    await espera(ms); // espera sem travar o programa
    yield i; // entrega o número ao for await...of
  }
}
